<?php require_once __DIR__.'/../../includes/bootstrap.php';require_role('admin');csrf_check();$d=$_SESSION['petugas_import']??null;if(!$d||$d['errors']||!$d['rows']){flash('danger','Preview tidak valid. Ulangi proses import.');redirect('/admin/dashboard.php');}$id=(int)$d['id_kegiatan'];try{$pdo->beginTransaction();$u=$pdo->prepare("SELECT id_user FROM users WHERE id_kegiatan=? AND role_user='petugas' FOR UPDATE");$u->execute([$id]);$uid=$u->fetchColumn();if(!$uid)throw new RuntimeException('Akun kegiatan tidak ditemukan.');$ins=$pdo->prepare('INSERT INTO petugas(id_kegiatan,id_user,nama_petugas,kecamatan) VALUES(?,?,?,?)');foreach($d['rows'] as $r)$ins->execute([$id,$uid,$r['nama_petugas'],$r['kecamatan']]);$pdo->commit();unset($_SESSION['petugas_import']);flash('success',count($d['rows']).' petugas berhasil diimpor.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('danger','Import dibatalkan. Tidak ada data yang disimpan karena terjadi konflik/duplikasi.');}redirect('/admin/kegiatan/detail.php?id='.$id);
